client_script:
function show_field(fieldname, show, required=false) {
    frappe.web_form.set_df_property(fieldname, 'hidden', show ? 0 : 1);
    frappe.web_form.set_df_property(fieldname, 'reqd', show && required ? 1 : 0);
}

function refresh_supplier_form() {
    let supplier_type = frappe.web_form.get_value('supplier_type');
    let whatsapp_same = frappe.web_form.get_value('whatsapp_same_as_mobile');
    let province = frappe.web_form.get_value('province');
    let has_tpin = frappe.web_form.get_value('has_tpin');
    let vat_registered = frappe.web_form.get_value('vat_registered');
    let payment_method = frappe.web_form.get_value('payment_method');
    let bank_name = frappe.web_form.get_value('bank_name');
    let bank_currency = frappe.web_form.get_value('bank_currency');
    let mobile_provider = frappe.web_form.get_value('mobile_money_provider');
    let payment_match = frappe.web_form.get_value('payment_name_matches_supplier');
    let capacity = frappe.web_form.get_value('approximate_capacity');

    // Supplier type
    show_field(
        'contact_person',
        supplier_type && supplier_type !== 'Individual / Farmer',
        true
    );

    show_field(
        'other_supplier_type',
        supplier_type === 'Other',
        true
    );

    let registered =
        supplier_type === 'Registered Business / Company' ||
        supplier_type === 'Cooperative / Association';

    show_field('registration_number', registered, true);
    show_field('vat_registered', registered, false);
    show_field('registration_certificate', registered, false);

    // WhatsApp
    show_field(
        'whatsapp_number',
        whatsapp_same === 'No',
        true
    );

    // Location
    show_field(
        'country_if_outside_zambia',
        province === 'Outside Zambia',
        true
    );

    // TPIN
    show_field(
        'tpin',
        has_tpin === 'Yes',
        true
    );

    show_field(
        'tpin_certificate',
        has_tpin === 'Yes',
        false
    );

    // VAT
    show_field(
        'vat_number',
        vat_registered === 'Yes',
        true
    );

    // Capacity unit
    show_field(
        'capacity_unit',
        !!capacity,
        false
    );

    // Bank fields
    let bank = payment_method === 'Bank Account';

    show_field('bank_name', bank, true);
    show_field('bank_account_name', bank, true);
    show_field('bank_account_number', bank, true);
    show_field('bank_branch', bank, false);
    show_field('bank_currency', bank, true);

    show_field(
        'other_bank_name',
        bank && bank_name === 'Other Bank / Financial Institution',
        true
    );

    show_field(
        'other_currency',
        bank && bank_currency === 'Other',
        true
    );

    // Mobile money fields
    let mobile = payment_method === 'Mobile Money';

    show_field('mobile_money_provider', mobile, true);
    show_field('mobile_money_number', mobile, true);
    show_field('mobile_money_registered_name', mobile, true);

    show_field(
        'other_mobile_money_provider',
        mobile && mobile_provider === 'Other',
        true
    );

    // Different payment account holder
    show_field(
        'payment_account_relationship',
        payment_match === 'No',
        true
    );

    show_field(
        'payment_account_reason',
        payment_match === 'No',
        true
    );
}

frappe.web_form.after_load = () => {
    refresh_supplier_form();
};

[
    'supplier_type',
    'whatsapp_same_as_mobile',
    'province',
    'has_tpin',
    'vat_registered',
    'payment_method',
    'bank_name',
    'bank_currency',
    'mobile_money_provider',
    'payment_name_matches_supplier',
    'approximate_capacity'
].forEach(fieldname => {
    frappe.web_form.on(fieldname, () => {
        refresh_supplier_form();
    });
});

frappe.web_form.on('mobile_number', (field, value) => {
    if (frappe.web_form.get_value('whatsapp_same_as_mobile') === 'Yes') {
        frappe.web_form.set_value('whatsapp_number', value);
    }
});

frappe.web_form.on('whatsapp_same_as_mobile', (field, value) => {
    if (value === 'Yes') {
        frappe.web_form.set_value(
            'whatsapp_number',
            frappe.web_form.get_value('mobile_number')
        );
    }
});

frappe.web_form.on('payment_method', (field, value) => {
    if (value === 'Bank Account') {
        frappe.web_form.set_value('mobile_money_provider', '');
        frappe.web_form.set_value('other_mobile_money_provider', '');
        frappe.web_form.set_value('mobile_money_number', '');
        frappe.web_form.set_value('mobile_money_registered_name', '');
    }

    if (value === 'Mobile Money') {
        frappe.web_form.set_value('bank_name', '');
        frappe.web_form.set_value('other_bank_name', '');
        frappe.web_form.set_value('bank_account_name', '');
        frappe.web_form.set_value('bank_account_number', '');
        frappe.web_form.set_value('bank_branch', '');
        frappe.web_form.set_value('bank_currency', '');
        frappe.web_form.set_value('other_currency', '');
    }

    refresh_supplier_form();
});

frappe.web_form.validate = () => {
    let declaration =
        frappe.web_form.get_value('supplier_declaration');

    if (!declaration) {
        frappe.msgprint(
            'Please confirm that the information provided is correct.'
        );
        return false;
    }

    return true;
};
